export function createAmbience(){let ctx=null,gain=null,on=false,room='outside',next=0;
 function note(freq,duration,volume=.012){const t=ctx.currentTime,o=ctx.createOscillator(),g=ctx.createGain();o.type='sine';o.frequency.setValueAtTime(freq,t);o.frequency.exponentialRampToValueAtTime(freq*1.3,t+duration*.3);g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(volume,t+.025);g.gain.exponentialRampToValueAtTime(.0001,t+duration);o.connect(g);g.connect(gain);o.start(t);o.stop(t+duration);o.onended=()=>{o.disconnect();g.disconnect();};}
 async function toggle(){const AC=globalThis.AudioContext||globalThis.webkitAudioContext;if(!AC)return {on:false,error:'此瀏覽器暫時不支援音效。'};if(!ctx){ctx=new AC();gain=ctx.createGain();gain.gain.value=0;gain.connect(ctx.destination);const buffer=ctx.createBuffer(1,ctx.sampleRate*3,ctx.sampleRate);const data=buffer.getChannelData(0);let last=0;for(let i=0;i<data.length;i++){last=(last+(Math.random()*2-1)*.02)/1.02;data[i]=last;}const noise=ctx.createBufferSource();noise.buffer=buffer;noise.loop=true;const filter=ctx.createBiquadFilter();filter.type='lowpass';filter.frequency.value=650;noise.connect(filter);filter.connect(gain);noise.start();}await ctx.resume();on=!on;gain.gain.setTargetAtTime(on?.22:0,ctx.currentTime,.3);return {on};}
 function update(time){if(!on||ctx?.state!=='running'||time<next)return;next=time+(room==='living'?1.7:3.6);if(room==='living')note(110+Math.random()*90,.055,.006);else {note(1700+Math.random()*900,.13,.016);note(2300,.23,.006);}}
 return {toggle,update,setRoom:r=>{if(room!==r){room=r;next=0;}},pause:()=>{if(ctx)gain.gain.setTargetAtTime(0,ctx.currentTime,.1);},resume:()=>{if(ctx&&on)gain.gain.setTargetAtTime(.22,ctx.currentTime,.2);},get on(){return on;}};
}
